cat > project/src/star4_switch.c <<'EOF'
/* Finite four-port collector.  The receive, transmit, and ACK sequence spaces
 * are logical (unwrapped); only the codec sees 24-bit physical PSNs.
 *
 * There is one bounded pool for every stage of an input's lifetime.  Cumulative
 * prefixes, rather than per-packet send flags, express all ACK dependencies.
 */
#include "epic_clean.h"
#include "offline_api.h"
#include <arpa/inet.h>
#include <stdlib.h>
#include <string.h>

#define PSN_MASK 0xffffffu
#define BIT(r) (1u << (r))

typedef struct {
    uint32_t p;
    uint8_t mask;
    bool occupied;
} slot_state_t;

typedef struct {
    int primitive, mode, root;
    uint32_t count, words, capacity, start, retired, occupied;
    uint32_t received[4], eligible[4], upstream[4], sent[4], acked[4];
    bool repeat[4];
    uint64_t counters[14]; /* certificate indices 18..31 */
    slot_state_t *slots;
    uint8_t *payloads;
    size_t stride;
    epic_port_t ports[4];
    epic_emit_fn emit;
    void *user;
} switch_ctx_t;

enum {
    RX_DATA, RX_ACK, TX_DATA, TX_ACK, ACCEPTED, DUPLICATE, BLOCKED,
    STALE, INVALID_WIRE, INVALID_ENDPOINT, IGNORED_ACK, FAILED_SEND,
    OVERWRITES, RESERVED
};

static uint32_t min32(uint32_t a, uint32_t b) { return a < b ? a : b; }
static uint8_t source_mask(const switch_ctx_t *c) {
    return c->primitive == EPIC_PRIM_BCAST ? BIT(c->root) : 15;
}
static slot_state_t *find_slot(switch_ctx_t *c, uint32_t p) {
    slot_state_t *s = &c->slots[p % c->capacity];
    return s->occupied && s->p == p ? s : NULL;
}
static uint8_t *slot_payload(switch_ctx_t *c, uint32_t p) {
    return c->payloads + (p % c->capacity) * c->stride;
}
static bool complete(switch_ctx_t *c, const slot_state_t *s) {
    return s->mask == source_mask(c);
}
static uint32_t output_count(switch_ctx_t *c, int rank) {
    switch (c->primitive) {
    case EPIC_PRIM_REDUCE: return rank == c->root ? c->count : 0;
    case EPIC_PRIM_BCAST: return rank != c->root ? c->count : 0;
    case EPIC_PRIM_ALLGATHER: return 3 * c->count;
    case EPIC_PRIM_REDUCESCATTER: return c->count / 4;
    default: return c->count;
    }
}
static int ordinal(int dest, int src) { return src - (src > dest); }
static int source_at(int dest, int ord) { return ord + (ord >= dest); }
static uint32_t input_for_output(switch_ctx_t *c, int dest, uint32_t q) {
    if (c->primitive == EPIC_PRIM_ALLGATHER) return q / 3;
    if (c->primitive == EPIC_PRIM_REDUCESCATTER) return dest * (c->count / 4) + q;
    return q;
}

/* Prefix of inputs with *all* outputs acknowledged.  Scatter's independent
 * destination spaces concatenate in input order, not receiver ACK order. */
static uint32_t output_acked_prefix(switch_ctx_t *c) {
    if (c->primitive == EPIC_PRIM_REDUCE) return c->acked[c->root];
    if (c->primitive == EPIC_PRIM_REDUCESCATTER) {
        uint32_t block = c->count / 4, prefix = 0;
        for (int r = 0; r < 4; ++r) {
            prefix = r * block + c->acked[r];
            if (c->acked[r] < block) break;
        }
        return prefix;
    }
    uint32_t prefix = c->count;
    for (int r = 0; r < 4; ++r) {
        if (c->primitive == EPIC_PRIM_BCAST && r == c->root) continue;
        uint32_t a = c->acked[r];
        if (c->primitive == EPIC_PRIM_ALLGATHER) a /= 3;
        prefix = min32(prefix, a);
    }
    return prefix;
}

static void update_received(switch_ctx_t *c, int rank) {
    uint32_t p = c->received[rank];
    while (p < c->count) {
        slot_state_t *s = find_slot(c, p);
        if (!s || !(s->mask & BIT(rank))) break;
        ++p;
    }
    c->received[rank] = p;
}

static void update_eligible(switch_ctx_t *c) {
    uint32_t common = output_acked_prefix(c);
    for (int r = 0; r < 4; ++r) {
        uint32_t safe;
        if (c->mode == EPIC_MODE_TERMINATION) safe = c->received[r];
        else if (c->primitive == EPIC_PRIM_ALLREDUCE || c->primitive == EPIC_PRIM_BARRIER)
            safe = c->acked[r];
        else if (c->primitive == EPIC_PRIM_ALLGATHER) {
            safe = c->count;
            for (int d = 0; d < 4; ++d) if (d != r) {
                /* Number of records from source r covered by this cumulative
                 * ACK, including a partially acknowledged gather input. */
                uint32_t n = (c->acked[d] + 2 - ordinal(d, r)) / 3;
                safe = min32(safe, n);
            }
        } else safe = common;
        c->eligible[r] = min32(c->received[r], safe);
    }
}

static void retire(switch_ctx_t *c) {
    uint32_t end = output_acked_prefix(c);
    uint8_t required = source_mask(c);
    for (int r = 0; r < 4; ++r) if (required & BIT(r))
        end = min32(end, c->upstream[r]);
    while (c->retired < end) {
        slot_state_t *s = find_slot(c, c->retired);
        if (!s || !complete(c, s)) break;
        s->occupied = false;
        s->mask = 0;
        --c->occupied;
        ++c->retired;
    }
}

static bool emit_ack(switch_ctx_t *c, int rank, uint32_t prefix) {
    epic_port_t *port = &c->ports[rank];
    uint8_t frame[62];
    size_t length = epic_build_roce_ack(frame, sizeof(frame), port->switch_mac,
        port->host_mac, port->switch_ip, port->host_ip, 4791, 4791,
        port->host_qpn, (c->start + prefix - 1) & PSN_MASK);
    if (!c->emit(c->user, rank, frame, length)) {
        ++c->counters[FAILED_SEND];
        return false;
    }
    ++c->counters[TX_ACK];
    return true;
}

static bool emit_result(switch_ctx_t *c, int dest, uint32_t q) {
    epic_port_t *port = &c->ports[dest];
    uint32_t p = input_for_output(c, dest, q);
    uint8_t *data = slot_payload(c, p);
    uint8_t frame[58 + EPIC_MAX_PAYLOAD_BYTES];
    uint32_t physical = (c->start + q) & PSN_MASK;
    size_t length;
    if (c->primitive == EPIC_PRIM_BCAST || c->primitive == EPIC_PRIM_ALLGATHER) {
        if (c->primitive == EPIC_PRIM_ALLGATHER)
            data += source_at(dest, q % 3) * c->words * 4;
        length = epic_build_roce_data_raw(frame, sizeof(frame), port->switch_mac,
            port->host_mac, port->switch_ip, port->host_ip, 4791, 4791,
            port->host_qpn, physical, data, c->words * 4);
    } else {
        length = epic_build_roce_data(frame, sizeof(frame), port->switch_mac,
            port->host_mac, port->switch_ip, port->host_ip, 4791, 4791,
            port->host_qpn, physical, (const int32_t *)data, c->words * 4);
    }
    if (!c->emit(c->user, dest, frame, length)) {
        ++c->counters[FAILED_SEND];
        return false;
    }
    ++c->counters[TX_DATA];
    return true;
}

/* Every opportunity terminates on its first failed local send.  Retirement
 * still runs, accounting for successes before that failure.  Retransmissions
 * are ephemeral requests: they never advance the new-output sent prefix. */
static int service(switch_ctx_t *c, int retry_rank) {
    int ok = 0;
    update_eligible(c);
    for (int r = 0; r < 4; ++r) {
        uint32_t e = c->eligible[r];
        if (e && (e > c->upstream[r] || c->repeat[r])) {
            if (!emit_ack(c, r, e)) goto done;
            c->upstream[r] = e;
            c->repeat[r] = false;
        }
    }
    if (retry_rank >= 0) {
        for (uint32_t q = c->acked[retry_rank]; q < c->sent[retry_rank]; ++q)
            if (!emit_result(c, retry_rank, q)) goto done;
    }
    for (int r = 0; r < 4; ++r) {
        uint32_t end = output_count(c, r);
        while (c->sent[r] < end) {
            uint32_t p = input_for_output(c, r, c->sent[r]);
            slot_state_t *s = find_slot(c, p);
            if (!s || !complete(c, s)) break;
            if (!emit_result(c, r, c->sent[r])) goto done;
            ++c->sent[r];
        }
    }
    ok = 1;
done:
    retire(c);
    return ok;
}

static void accept_data(switch_ctx_t *c, int rank, uint32_t p, const uint8_t *payload) {
    if (p < c->retired) {
        ++c->counters[STALE];
        c->repeat[rank] = true;
        return;
    }
    if (p - c->retired >= c->capacity) {
        ++c->counters[BLOCKED];
        return;
    }
    slot_state_t *s = find_slot(c, p);
    if (s && (s->mask & BIT(rank))) {
        ++c->counters[DUPLICATE];
        c->repeat[rank] = true;
        return;
    }
    if (!s) {
        s = &c->slots[p % c->capacity];
        /* The admission window contains at most one logical identity at each
         * physical slot index.  A different occupied identity is impossible. */
        if (s->occupied) abort();
        *s = (slot_state_t){ .p = p, .occupied = true };
        ++c->occupied;
        memset(slot_payload(c, p), 0, c->stride);
    }
    uint8_t *data = slot_payload(c, p);
    if (c->primitive == EPIC_PRIM_BCAST) memcpy(data, payload, 4 * c->words);
    else if (c->primitive == EPIC_PRIM_ALLGATHER)
        memcpy(data + rank * c->words * 4, payload, c->words * 4);
    else {
        uint32_t *accum = (uint32_t *)data;
        for (uint32_t j = 0; j < c->words; ++j) {
            uint32_t word;
            memcpy(&word, payload + 4 * j, 4);
            accum[j] += ntohl(word); /* unsigned, including overflow */
        }
    }
    s->mask |= BIT(rank);
    ++c->counters[ACCEPTED];
    update_received(c, rank);
}

static int handle_packet(switch_ctx_t *c, int rank, const uint8_t *frame, size_t length) {
    epic_roce_packet_t packet;
    if (!epic_parse_roce(frame, length, &packet) ||
        (packet.is_data && packet.payload_len != c->words * 4)) {
        ++c->counters[INVALID_WIRE];
        return 1;
    }
    epic_port_t *port = &c->ports[rank];
    uint32_t p = (packet.psn - c->start) & PSN_MASK;
    if (memcmp(frame, port->switch_mac, 6) || memcmp(frame + 6, port->host_mac, 6) ||
        packet.src_ip != port->host_ip || packet.dst_ip != port->switch_ip ||
        packet.dst_qpn != port->switch_qpn ||
        (packet.is_data && (p >= c->count || !(source_mask(c) & BIT(rank))))) {
        ++c->counters[INVALID_ENDPOINT];
        return 1;
    }
    if (packet.is_data) {
        ++c->counters[RX_DATA];
        accept_data(c, rank, p, packet.payload);
    } else {
        ++c->counters[RX_ACK];
        uint32_t prefix = (packet.psn - c->start + 1) & PSN_MASK;
        if (prefix > c->acked[rank] && prefix <= c->sent[rank]) c->acked[rank] = prefix;
        else ++c->counters[IGNORED_ACK];
    }
    return service(c, -1);
}
