 * before the caller checks any endpoints or classifies DATA admission. */
bool epic_parse_roce(const uint8_t *frame, size_t frame_len, epic_roce_packet_t *out) {
    if (!frame || !out) return false;
    memset(out, 0, sizeof(*out));
    if (frame_len < 58) return false;
    const epic_eth_t *eth = (const epic_eth_t *)frame;
    const epic_ipv4_t *ip = (const epic_ipv4_t *)(frame + 14);
    if (ntohs(eth->ether_type) != ETHERTYPE_IPV4 || ip->version_ihl != 0x45 ||
        ip->protocol != 17 || (size_t)ntohs(ip->total_length) + 14 != frame_len ||
        (ntohs(ip->flags_frag_off) != 0 && ntohs(ip->flags_frag_off) != 0x4000) ||
        epic_ipv4_checksum(ip, 20) != 0) return false;
    const epic_udp_t *udp = (const epic_udp_t *)(frame + 34);
    if (ntohs(udp->length) != ntohs(ip->total_length) - 20 ||
        ntohs(udp->src_port) != 4791 || ntohs(udp->dst_port) != 4791 ||
        udp->checksum != 0) return false;
    const epic_bth_t *bth = (const epic_bth_t *)(frame + 42);
    if (bth->se_m_pad != 0 || ntohs(bth->pkey) != 0xffff ||
        (ntohl(bth->qpn) >> 24) != 0) return false;
    uint32_t apsn = ntohl(bth->apsn), psn = apsn & 0xffffffu;
    if (bth->opcode == ROCE_OPCODE_ACK) {
        if (frame_len != 62 || (apsn >> 24) != 0) return false;
        uint32_t body;
        memcpy(&body, frame + 54, 4);
        body = ntohl(body);
        if (body != (0x1f000000u | ((psn + 1) & 0xffffffu))) return false;
        out->is_ack = true;
        out->msn = body & 0xffffffu;
    } else if (bth->opcode == ROCE_OPCODE_SEND_ONLY) {
        if ((apsn >> 24) != 0x80 || frame_len > 58 + EPIC_MAX_PAYLOAD_BYTES) return false;
        out->is_data = true;
        out->payload = frame + 54;
        out->payload_len = frame_len - 58;
    } else return false;
    uint32_t icrc;
    memcpy(&icrc, frame + frame_len - 4, 4); /* wire ICRC is little endian */
    if (icrc != epic_compute_icrc(frame, frame_len)) return false;
    out->valid = true;
    out->opcode = bth->opcode;
    out->dst_qpn = ntohl(bth->qpn);
    out->psn = psn;
    out->src_ip = ip->src_ip; out->dst_ip = ip->dst_ip;
    out->src_port = ntohs(udp->src_port); out->dst_port = ntohs(udp->dst_port);
    return true;
}
